  function openDispatcherDialog() {
    const dispatcher = cur();
    if (!dispatcher || dispatcher.role !== "dispatcher" || !isLocalTurn()) return;
    const pawns = state.players.filter((player) => player !== dispatcher);
    if (!pawns.length) return;
    const dlg = dialogShell(
      "تحريك قطعة زميل",
      '<div class="pan-dialog-intro"><span>🎯</span><p>اختر قطعة زميل لتحريكها. يمكنك نقلها إلى مدينة مجاورة، أو إلى أي مدينة يوجد فيها لاعب آخر. تستهلك <strong>حركة واحدة</strong>.</p></div>' +
      '<div class="pan-pawn-grid">' +
      pawns.map((pawn) =>
        '<button type="button" class="pan-pawn-option" data-dispatch-pawn="' + pawn.index + '" style="--pc:' + pColor(pawn.index) + '">' +
        '<span class="pan-pawn-token">' + (pawn.index + 1) + "</span>" +
        "<strong>" + U.escape(pawn.name) + "</strong><small>" + roleOf(pawn).name + " · " + U.escape(cityName(pawn.city)) + "</small>" +
        "</button>"
      ).join("") +
      "</div>",
      [{ label: "إلغاء", value: "cancel" }]
    );

    const showDestinations = (pawn) => {
      const adjacent = ADJ[pawn.city];
      const occupied = [];
      state.players.forEach((other) => {
        if (other === pawn || other.city === pawn.city) return;
        if (!occupied.includes(other.city)) occupied.push(other.city);
      });
      const groups = [];
      groups.push({
        id: "ground",
        title: "خطوة برية / بحرية",
        hint: "إلى مدينة متصلة مباشرة — بلا بطاقة",
        items: adjacent.map((id) => cityOptionHTML(id, "ground", "مدينة مجاورة")).join(""),
      });

      const jumps = occupied.filter((id) => !adjacent.includes(id));
      if (jumps.length) {
        groups.push({
          id: "jump",
          title: "الانتقال إلى قطعة زميل",
          hint: "نقلة الموزّع الخاصة — بلا بطاقة",
          items: jumps.map((id) => cityOptionHTML(id, "jump", "فيها قطعة زميل")).join(""),
        });
      }

      if (stationAt(pawn.city)) {
        const stations = Object.keys(state.stations).filter((id) => id !== pawn.city);
        if (stations.length) {
          groups.push({
            id: "shuttle",
            title: "مكوك محطات الأبحاث",
            hint: "بين محطتين — بلا بطاقة",
            items: stations.map((id) => cityOptionHTML(id, "shuttle", "مكوك المحطات")).join(""),
          });
        }
      }

      const directCities = [];
      cityCards(dispatcher.hand).forEach((card) => {
        if (card.city !== pawn.city && !directCities.includes(card.city)) directCities.push(card.city);
      });
      if (directCities.length) {
        groups.push({
          id: "direct",
          title: "رحلات مباشرة",
          hint: "تجاهل بطاقة وجهة من يد الموزّع",
          items: directCities.map((id) => cityOptionHTML(id, "direct", "بطاقة وجهة")).join(""),
        });
      }

      if (hasCardFor(dispatcher, pawn.city)) {
        groups.push({
          id: "charter",
          title: "رحلة خاصة",
          hint: "تجاهل بطاقة مدينة القطعة من يد الموزّع للسفر إلى أي مدينة",
          items: CITIES.filter((city) => city.id !== pawn.city).map((city) => cityOptionHTML(city.id, "charter", "بطاقة المدينة الحالية")).join(""),
        });
      }

      dlg.body.innerHTML =
        '<div class="pan-dialog-intro"><span>🎯</span><p>قطعة <strong>' + U.escape(pawn.name) + "</strong> في <strong>" + U.escape(cityName(pawn.city)) + "</strong>. اختر وجهة وطريقة النقل؛ ستُخصم <strong>حركة واحدة</strong> من إجراءات الموزّع.</p></div>" +
        groups.map((group) =>
          '<section class="pan-dialog-group"><div class="pan-dialog-group-head"><strong>' + group.title + "</strong><span>" + group.hint + "</span></div>" +
          '<div class="pan-city-grid">' + group.items + "</div></section>"
        ).join("") +
        '<div class="pan-dialog-actions"><button type="button" class="bg-btn small" data-dispatch-back>↩ رجوع إلى القطع</button></div>';
      dlg.body.querySelectorAll("[data-move-city]").forEach((button) => {
        button.addEventListener("click", () => {
          const destination = button.getAttribute("data-move-city");
          const mode = button.getAttribute("data-move-mode");
          const ok = mode === "jump" ? dispatcherQuickMove(pawn.index, destination) : dispatcherTravel(pawn.index, destination, mode);
          if (ok) dlg.close("done");
        });
      });
      const back = dlg.body.querySelector("[data-dispatch-back]");
      if (back) {
        back.addEventListener("click", () => {
          dlg.close("back");
          openDispatcherDialog();
        });
      }
    };

    dlg.body.querySelectorAll("[data-dispatch-pawn]").forEach((button) => {
      button.addEventListener("click", () => {
        const pawn = playerAt(parseInt(button.getAttribute("data-dispatch-pawn"), 10));
        if (pawn) showDestinations(pawn);
      });
    });
  }

